def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    used = np.zeros_like(g, dtype=bool)
    sevens = set(zip(*np.where(g == 7)))

    def find7(cells, horiz):
        # return the end cell of the domino that is nearer to a 7 on its line
        (a, b) = cells
        best = None
        if horiz:
            y = a[0]
            xs = [x for (yy, x) in sevens if yy == y]
            for x in xs:
                d1, d2 = abs(x - a[1]), abs(x - b[1])
                d = min(d1, d2)
                end = a if d1 < d2 else b
                if best is None or d < best[0]:
                    best = (d, end)
        else:
            x = a[1]
            ys = [y for (y, xx) in sevens if xx == x]
            for y in ys:
                d1, d2 = abs(y - a[0]), abs(y - b[0])
                d = min(d1, d2)
                end = a if d1 < d2 else b
                if best is None or d < best[0]:
                    best = (d, end)
        return None if best is None else best[1]

    for y in range(H):
        for x in range(W):
            if used[y, x] or g[y, x] not in (1, 6):
                continue
            for dy, dx, horiz in ((0, 1, True), (1, 0, False)):
                ny, nx = y + dy, x + dx
                if ny >= H or nx >= W or used[ny, nx]:
                    continue
                if g[ny, nx] not in (1, 6) or g[ny, nx] == g[y, x]:
                    continue
                cells = ((y, x), (ny, nx))
                end = find7(cells, horiz)
                if end is None:
                    continue
                other = cells[1] if end == cells[0] else cells[0]
                changed = g[end] != 6
                g[end] = 6
                g[other] = 1
                used[y, x] = used[ny, nx] = True
                if changed:
                    emit(g.copy(), f"Flip domino at {cells} so its 6 end faces the 7 on its {'row' if horiz else 'column'}.")
                break
    emit(g.copy(), "All 1/6 dominoes now point their 6 toward the 7 on their line.")
    return g
